package com.reconciliation.application.port;

import java.io.IOException;
import java.io.InputStream;

/**
 * Durable storage for uploaded files. Keys are generated by the application,
 * never derived from client input, so no path can be injected.
 *
 * <p>Implementations must make {@link #store} atomic from the reader's point of
 * view: a key is either absent or holds the complete content, never a partial file.
 */
public interface FileStorage {

    /** Streams {@code content} to {@code key}. Returns bytes written. */
    long store(String key, InputStream content) throws IOException;

    /** Opens the stored content for sequential reading. */
    InputStream open(String key) throws IOException;

    /** Deletes a key; silently ignores a missing one. Also removes partial writes. */
    void delete(String key) throws IOException;

    /** Whether the storage can currently accept writes (used by readiness). */
    boolean isWritable();
}
